## 7. Authentication & Authorization

| Option | When to use |
|--------|-------------|
| **Auth0 / Okta** | If you need social login, MFA, or enterprise SSO |
| **NextAuth.js** | Full‑stack solution with JWT, OAuth, email magic links |
| **Custom JWT** | Lightweight, if you already have a backend that issues tokens |

> **Example** – NextAuth.js with email/password:

```ts
// src/pages/api/auth/[...nextauth].ts
import NextAuth from 'next-auth';
import CredentialsProvider from 'next-auth/providers/credentials';
import { verifyPassword } from '@/lib/auth';

export default NextAuth({
  providers: [
    CredentialsProvider({
      name: 'Credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' },
      },
      async authorize(credentials) {
        const user = await findUserByEmail(credentials.email);
        if (!user || !(await verifyPassword(credentials.password, user.passwordHash))) {
          throw new Error('Invalid credentials');
        }
        return { id: user.id, email: user.email };
      },
    }),
  ],
  session: { strategy: 'jwt' },
  callbacks: {
    async jwt({ token, user }) {
      if (user) token.id = user.id;
      return token;
    },
    async session({ session, token }) {
      session.user.id = token.id;
      return session;
    },
  },
});
```

