## 8. Payment Integration

| Provider | Notes |
|----------|-------|
| **Stripe** | Most popular, supports webhooks, Checkout, Elements |
| **PayPal** | Good for international markets |
| **Square** | Good for physical stores |

### 8.1 Stripe Checkout Session (Serverless)

```ts
// src/pages/api/stripe-checkout.ts
import { NextApiRequest, NextApiResponse } from 'next';
import Stripe from 'stripe';
import { getCartItems } from '@/lib/cart';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, { apiVersion: '2023-10-16' });

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).end();

  const { items } = req.body; // [{ priceId, quantity }]
  try {
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: items,
      mode: 'payment',
      success_url: `${process.env.NEXT_PUBLIC_SITE_URL}/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${process.env.NEXT_PUBLIC_SITE_URL}/cart`,
    });
    res.status(200).json({ sessionId: session.id });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create checkout session' });
  }
}
```

### 8.2 Frontend Trigger

```tsx
// src/features/cart/CheckoutButton.tsx
import { useMutation } from '@tanstack/react-query';
import { useRouter } from 'next/router';
import { Button } from '@/components/ui/Button';

export const CheckoutButton = () => {
  const router = useRouter();
  const mutation = useMutation(async () => {
    const res = await fetch('/api/stripe-checkout', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: /* cart items */ }),
    });
    const { sessionId } = await res.json();
    return sessionId;
  });

  const handleClick = async () => {
    const sessionId = await mutation.mutateAsync();
    const stripe = await import('stripe-js'); // dynamic import
    const stripeObj = await stripe.loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);
    await stripeObj.redirectToCheckout({ sessionId });
  };

  return (
    <Button onClick={handleClick} disabled={mutation.isLoading}>
      {mutation.isLoading ? 'Processing…' : 'Checkout'}
    </Button>
  );
};
```

